import { selectedOperatingSystemServices } from '../services/OperatingSystemServices';
import { spawnProcess } from '../services/packageManagerProcess';

export type NpmCommandResult = {
  error?: Error;
  isTimedOut: boolean;
  status: number | null;
  stderr: string;
  stdout: string;
};

export const runNpm = ({
  args,
  env,
  onStarted,
  stdio = 'pipe',
  timeoutMs,
}: {
  args: string[];
  env: NodeJS.ProcessEnv;
  onStarted?: (processId: number) => void;
  stdio?: 'inherit' | 'pipe';
  timeoutMs?: number;
}): Promise<NpmCommandResult> =>
  new Promise((resolve) => {
    const { operatingSystemFamily, projectProcesses } =
      selectedOperatingSystemServices;
    const isProcessGroupLeader =
      timeoutMs !== undefined && operatingSystemFamily === 'posix';
    let stdout = '';
    let stderr = '';
    let isTimedOut = false;
    let spawnError: Error | undefined;
    const child = spawnProcess(
      { packageManager: 'npm', args },
      {
        detached: isProcessGroupLeader,
        env,
        stdio: stdio === 'inherit' ? 'inherit' : ['ignore', 'pipe', 'pipe'],
      },
    );
    if (child.pid !== undefined) onStarted?.(child.pid);
    child.stdout?.setEncoding('utf8');
    child.stdout?.on('data', (chunk: string) => {
      stdout += chunk;
    });
    child.stderr?.setEncoding('utf8');
    child.stderr?.on('data', (chunk: string) => {
      stderr += chunk;
    });
    child.on('error', (error) => {
      spawnError = error;
      stderr += error.message;
    });
    const stopProcessTree = async (): Promise<void> => {
      if (isProcessGroupLeader && child.pid !== undefined) {
        process.kill(-child.pid, 'SIGTERM');
        return;
      }
      await projectProcesses.terminate(child, { isForceful: false, env });
    };
    const timeout =
      timeoutMs === undefined
        ? undefined
        : setTimeout(() => {
            isTimedOut = true;
            stopProcessTree().catch((error: unknown) => {
              stderr += String(error);
            });
          }, timeoutMs);
    child.once('close', (status) => {
      clearTimeout(timeout);
      resolve({
        error: spawnError,
        isTimedOut,
        status: isTimedOut ? null : status,
        stderr,
        stdout,
      });
    });
  });
